54	    /// Returns all [Reference] captured by the closure argument of the React hook.
55	    /// See [react_hook_with_dependency].
56	    pub fn all_captures(&self, model: &SemanticModel) -> impl Iterator<Item = Capture> {
57	        self.closure_node
58	            .as_ref()
59	            .and_then(|node| AnyJsFunctionExpression::try_from(node.clone()).ok())
60	            .map(|function_expression| {
61	                let closure = function_expression.closure(model);
62	                let range = *closure.closure_range();
63	                closure
64	                    .descendents()
65	                    .flat_map(|closure| closure.all_captures())
66	                    .filter(move |capture| capture.declaration_range().intersect(range).is_none())
67	            })
68	            .into_iter()
69	            .flatten()
70	    }
