111	/// Checks whether the given call expression calls a React hook, based on the
112	/// official convention for React hook naming: Hook names must start with `use`
113	/// followed by a capital letter.
114	///
115	/// Source: https://react.dev/learn/reusing-logic-with-custom-hooks#hook-names-always-start-with-use
116	pub(crate) fn is_react_hook_call(call: &JsCallExpression) -> bool {
117	    let Some(name) = get_untrimmed_callee_name(call) else {
118	        return false;
119	    };
120	
121	    let name = name.text_trimmed();
122	    name.starts_with("use") && name.chars().nth(3).is_some_and(char::is_uppercase)
123	}
