125	const HOOKS_WITH_DEPS_API: [&str; 6] = [
126	    "useEffect",
127	    "useLayoutEffect",
128	    "useInsertionEffect",
129	    "useCallback",
130	    "useMemo",
131	    "useImperativeHandle",
132	];
