83	/// Verifies whether the call expression is at the top level of the component,
84	/// and returns the function node if so.
85	fn enclosing_function_if_call_is_at_top_level(
86	    call: &JsCallExpression,
87	) -> Option<AnyJsFunctionOrMethod> {
88	    let mut prev_node = None;
89	
90	    for node in call.syntax().ancestors() {
91	        if let Some(enclosing_function) = AnyJsFunctionOrMethod::cast_ref(&node) {
92	            return Some(enclosing_function);
93	        }
94	
95	        if let Some(prev_node) = prev_node {
96	            if is_conditional_expression(&node, &prev_node) {
97	                return None;
98	            }
99	        }
100	
101	        prev_node = Some(node);
102	    }
103	
104	    None
105	}
